-- METSL_MapCore
-- Middle-earth True Start Location: multiplayer-safe map generation.
--
-- Original concept/data: Yenyang (Middle Earth True Start Location), based on Gedemon's
-- "Yet (not) Another Earth Maps Pack" and FramedArchitecture's work.
--
-- Rewrite for multiplayer:
--  * the map terrain is embedded as Lua data (converted from the original .Civ5Map files),
--    so the map is generated by a normal Lua map script on every machine;
--  * all settings come from map-script options (synchronised by the game in MP lobbies)
--    instead of a local per-PC user database;
--  * only the synchronised map RNG (Map.Rand) is used, never math.random;
--  * the coordinate mix-ups of the original resource code are fixed (true X/Y everywhere).
--------------------------------------------------------------

include("MapGenerator")
include("METSL_MapDefs")

local METSL_Key = nil

function METSL_UseMap(key)
	METSL_Key = key
end

local function Def()
	return METSL_Maps[METSL_Key]
end

local function Data()
	return METSL_MapData[METSL_Key]
end

local function Options()
	if not METSL_CachedOptions then
		METSL_CachedOptions = METSL_ReadOptions(Def(), Map.GetCustomOption)
	end
	return METSL_CachedOptions
end

local function Rand(n, log)
	-- returns 1..n using the synchronised map RNG
	if n <= 1 then return 1 end
	return Map.Rand(n, log or "METSL") + 1
end

------------------------------------------------------------------------------
-- Map script interface
------------------------------------------------------------------------------
function GetMapScriptInfo()
	local def = Def()
	return {
		Name = def.Name,
		Description = def.Description,
		IsAdvancedMap = false,
		SupportsSinglePlayer = true,
		SupportsMultiplayer = true,
		IconIndex = 5,
		CustomOptions = METSL_BuildCustomOptions(def),
	}
end

function GetMapInitData(worldSize)
	local data = Data()
	return {
		Width = data.W,
		Height = data.H,
		WrapX = data.WrapX,
		WrapY = false,
	}
end

------------------------------------------------------------------------------
-- Embedded map data decoding
------------------------------------------------------------------------------
local ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local DECODE = {}
for i = 1, #ALPHA do
	DECODE[string.byte(ALPHA, i)] = i - 1
end

local function Field(name, x, y)
	local rows = Data()[name]
	if not rows then return 0 end
	return DECODE[string.byte(rows[y + 1], x + 1)]
end

local function IsWaterTerrainName(name)
	return name == "TERRAIN_COAST" or name == "TERRAIN_OCEAN"
end

local function CheckMapSize()
	local w, h = Map.GetGridSize()
	local data = Data()
	if w ~= data.W or h ~= data.H then
		print("METSL ERROR: grid size " .. w .. "x" .. h .. " does not match map data " .. data.W .. "x" .. data.H)
		return false
	end
	return true
end

function GeneratePlotTypes()
	print("METSL: setting plot types for " .. METSL_Key)
	CheckMapSize()
	local data = Data()
	for y = 0, data.H - 1 do
		for x = 0, data.W - 1 do
			local plot = Map.GetPlot(x, y)
			local tName = data.Terrains[Field("terrain", x, y) + 1]
			local elev = Field("elevation", x, y)
			local plotType
			if IsWaterTerrainName(tName) then
				plotType = PlotTypes.PLOT_OCEAN
			elseif elev == 2 then
				plotType = PlotTypes.PLOT_MOUNTAIN
			elseif elev == 1 then
				plotType = PlotTypes.PLOT_HILLS
			else
				plotType = PlotTypes.PLOT_LAND
			end
			plot:SetPlotType(plotType, false, false)
		end
	end
end

function GenerateTerrain()
	print("METSL: setting terrain")
	local data = Data()
	local terrainIDs = {}
	for i, name in ipairs(data.Terrains) do
		local t = GameInfo.Terrains[name]
		terrainIDs[i - 1] = t and t.ID or GameInfo.Terrains.TERRAIN_GRASS.ID
	end
	for y = 0, data.H - 1 do
		for x = 0, data.W - 1 do
			Map.GetPlot(x, y):SetTerrainType(terrainIDs[Field("terrain", x, y)], false, false)
		end
	end
end

function AddRivers()
	print("METSL: setting rivers")
	local data = Data()
	local F = FlowDirectionTypes
	for y = 0, data.H - 1 do
		for x = 0, data.W - 1 do
			local r = Field("river", x, y)
			if r > 0 then
				local plot = Map.GetPlot(x, y)
				-- see tools/map2lua.py for the (verified) bit layout
				if r % 2 == 1 then
					local flow = (math.floor(r / 8) % 2 == 1) and F.FLOWDIRECTION_SOUTH or F.FLOWDIRECTION_NORTH
					plot:SetWOfRiver(true, flow)
				end
				if math.floor(r / 2) % 2 == 1 then
					local flow = (math.floor(r / 16) % 2 == 1) and F.FLOWDIRECTION_NORTHEAST or F.FLOWDIRECTION_SOUTHWEST
					plot:SetNWOfRiver(true, flow)
				end
				if math.floor(r / 4) % 2 == 1 then
					local flow = (math.floor(r / 32) % 2 == 1) and F.FLOWDIRECTION_NORTHWEST or F.FLOWDIRECTION_SOUTHEAST
					plot:SetNEOfRiver(true, flow)
				end
			end
		end
	end
end

function AddLakes()
	-- lakes are part of the map data
end

function AddFeatures()
	print("METSL: setting features")
	local data = Data()
	local featureIDs = {}
	for i, name in ipairs(data.Features) do
		local f = GameInfo.Features[name]
		featureIDs[i] = f and f.ID or -1
	end
	local wonderIDs = {}
	for i, name in ipairs(data.Wonders or {}) do
		local f = GameInfo.Features[name]
		wonderIDs[i] = f and f.ID or -1
	end
	for y = 0, data.H - 1 do
		for x = 0, data.W - 1 do
			local plot = Map.GetPlot(x, y)
			local f = Field("feature", x, y)
			if f > 0 and featureIDs[f] and featureIDs[f] >= 0 then
				plot:SetFeatureType(featureIDs[f], -1)
			end
			if data.wonder then
				local w = Field("wonder", x, y)
				if w > 0 and wonderIDs[w] and wonderIDs[w] >= 0 then
					plot:SetFeatureType(wonderIDs[w], -1)
				end
			end
		end
	end
end

function DetermineContinents()
	print("METSL: setting continent art")
	local data = Data()
	for y = 0, data.H - 1 do
		for x = 0, data.W - 1 do
			local plot = Map.GetPlot(x, y)
			local c = Field("continent", x, y)
			if plot:IsWater() then
				plot:SetContinentArtType(0)
			else
				if c == 0 then c = 4 end -- land created by the script (e.g. natural wonder islet)
				plot:SetContinentArtType(c)
			end
		end
	end
end

------------------------------------------------------------------------------
-- Natural wonders
------------------------------------------------------------------------------
local function PlaceNaturalWonders(def)
	print("METSL: placing natural wonders")
	for _, nw in ipairs(def.NaturalWonders) do
		local feature = GameInfo.Features[nw.Feature]
		local plot = Map.GetPlot(nw.X, nw.Y)
		if feature and plot then
			print("  " .. nw.Feature .. " at " .. nw.X .. "," .. nw.Y)
			plot:SetPlotType(PlotTypes.PLOT_LAND, false, false)
			plot:SetTerrainType(GameInfo.Terrains.TERRAIN_PLAINS.ID, false, false)
			plot:SetFeatureType(feature.ID, -1)
		end
	end
	Map.RecalculateAreas()
end

------------------------------------------------------------------------------
-- Starting plots
------------------------------------------------------------------------------
local g_Starts = {} -- list of starting plots already assigned

local function IsValidStartPlot(plot)
	if plot == nil then return false end
	if plot:IsWater() or plot:IsMountain() or plot:IsImpassable() then return false end
	local feature = plot:GetFeatureType()
	if feature ~= -1 and GameInfo.Features[feature] and GameInfo.Features[feature].NaturalWonder then return false end
	return true
end

local function TooCloseToStarts(plot, minDist)
	local x, y = plot:GetX(), plot:GetY()
	for _, s in ipairs(g_Starts) do
		if Map.PlotDistance(x, y, s:GetX(), s:GetY()) < minDist then
			return true
		end
	end
	return false
end

-- If the configured plot is not usable (water/mountain), use the nearest usable one.
local function ValidateStartPlot(x, y)
	local plot = Map.GetPlot(x, y)
	if plot and IsValidStartPlot(plot) then return plot end
	for radius = 1, 3 do
		for dy = -radius, radius do
			for dx = -radius, radius do
				local p = Map.PlotXYWithRangeCheck(x, y, dx, dy, radius)
				if p and Map.PlotDistance(x, y, p:GetX(), p:GetY()) == radius and IsValidStartPlot(p) and not p:IsStartingPlot() then
					print("  start (" .. x .. "," .. y .. ") not usable, moved to (" .. p:GetX() .. "," .. p:GetY() .. ")")
					return p
				end
			end
		end
	end
	return plot
end

local TERRAIN_SCORE = nil
local function PlotScore(plot)
	if not TERRAIN_SCORE then
		TERRAIN_SCORE = {}
		local s = { TERRAIN_GRASS = 3, TERRAIN_PLAINS = 3, TERRAIN_TUNDRA = 1, TERRAIN_DESERT = 0, TERRAIN_SNOW = 0, TERRAIN_COAST = 1, TERRAIN_OCEAN = 0 }
		for row in GameInfo.Terrains() do
			TERRAIN_SCORE[row.ID] = s[row.Type] or 1
		end
	end
	if plot:IsMountain() then return 0 end
	local score = TERRAIN_SCORE[plot:GetTerrainType()] or 1
	if plot:IsHills() then score = score + 1 end
	if plot:IsRiver() or plot:IsFreshWater() then score = score + 1 end
	if plot:GetFeatureType() == FeatureTypes.FEATURE_ICE then score = 0 end
	return score
end

local function StartFertility(plot)
	local x, y = plot:GetX(), plot:GetY()
	local total = 0
	for dy = -2, 2 do
		for dx = -2, 2 do
			local p = Map.PlotXYWithRangeCheck(x, y, dx, dy, 2)
			if p then total = total + PlotScore(p) end
		end
	end
	if plot:IsRiver() then total = total + 4 end
	if plot:IsCoastalLand() then total = total + 2 end
	return total
end

-- Random but sensible starting plot (synchronised RNG), for civs without a TSL.
local function FindRandomStart(minDist)
	for dist = minDist, 2, -1 do
		local candidates = {}
		for i, plot in Plots() do
			if IsValidStartPlot(plot) and not plot:IsStartingPlot() and plot:Area():GetNumTiles() >= 12
				and not TooCloseToStarts(plot, dist) then
				table.insert(candidates, { plot = plot, score = StartFertility(plot), index = i })
			end
		end
		if #candidates > 0 then
			table.sort(candidates, function(a, b)
				if a.score == b.score then return a.index < b.index end
				return a.score > b.score
			end)
			local pool = math.max(1, math.floor(#candidates / 4))
			return candidates[Rand(pool, "METSL random start")].plot
		end
	end
	return nil
end

local function AssignStart(player, plot)
	player:SetStartingPlot(plot)
	table.insert(g_Starts, plot)
end

local function PlaceMajorCivs(def)
	print("METSL: placing major civilizations")
	local tableName = METSL_CivStartTable(def)
	local used = {}
	local pending = {}
	for i = 0, GameDefines.MAX_MAJOR_CIVS - 1 do
		local player = Players[i]
		if player and player:IsEverAlive() then
			local civ = GameInfo.Civilizations[player:GetCivilizationType()]
			local placed = false
			if civ and GameInfo[tableName] then
				for row in GameInfo[tableName]() do
					if row.Type == civ.Type and not used[row.Type] then
						local plot = ValidateStartPlot(row.X, row.Y)
						if plot then
							used[row.Type] = true
							AssignStart(player, plot)
							placed = true
							print("  " .. civ.Type .. " -> (" .. plot:GetX() .. "," .. plot:GetY() .. ")")
						end
						break
					end
				end
			end
			if not placed then
				table.insert(pending, player)
			end
		end
	end
	-- civilizations without a TSL (or duplicates): random placement
	for _, player in ipairs(pending) do
		local plot = FindRandomStart(9)
		if plot then
			AssignStart(player, plot)
			print("  player " .. player:GetID() .. " has no TSL, random start (" .. plot:GetX() .. "," .. plot:GetY() .. ")")
		end
	end
end

local function PlaceMinorCivs(def, opt)
	print("METSL: placing city-states, placement option = " .. opt.MinorPlacement)
	local tableName = METSL_MinorStartTable(def)
	local pending = {}
	for i = GameDefines.MAX_MAJOR_CIVS, GameDefines.MAX_CIV_PLAYERS - 1 do
		local player = Players[i]
		if player and player:IsEverAlive() and player:IsMinorCiv() then
			local minor = GameInfo.MinorCivilizations[player:GetMinorCivType()]
			local placed = false
			if minor and opt.MinorPlacement ~= METSL_MINOR_ALL_RANDOM and GameInfo[tableName] then
				for row in GameInfo[tableName]() do
					if row.Type == minor.Type then
						local plot = ValidateStartPlot(row.X, row.Y)
						if plot and not plot:IsStartingPlot() then
							AssignStart(player, plot)
							placed = true
							print("  " .. minor.Type .. " -> (" .. plot:GetX() .. "," .. plot:GetY() .. ")")
						end
						break
					end
				end
			end
			if not placed then
				table.insert(pending, player)
			end
		end
	end
	for _, player in ipairs(pending) do
		-- With "Only TSL" these city-states are removed on turn 0 by METSL_InGame.lua; they still
		-- need a valid plot so the game can create their units.
		local plot = FindRandomStart(6)
		if plot then
			AssignStart(player, plot)
			print("  minor player " .. player:GetID() .. " random start (" .. plot:GetX() .. "," .. plot:GetY() .. ")")
		end
	end
end

------------------------------------------------------------------------------
-- Resources
------------------------------------------------------------------------------
local g_RegionsByPlot = nil   -- [plotIndex] = { regionType, ... }
local g_ExcludedIn = nil      -- [regionType][resourceType] = true

local function BuildRegionData(def)
	g_RegionsByPlot = {}
	g_ExcludedIn = {}
	local posTable = GameInfo[METSL_RegionPosTable(def)]
	local excTable = GameInfo[METSL_RegionExcTable(def)]
	if not posTable or not excTable then return end
	local w, h = Map.GetGridSize()
	for row in posTable() do
		for x = row.X, row.X + row.Width do
			for y = row.Y, row.Y + row.Height do
				if x >= 0 and x < w and y >= 0 and y < h then
					local idx = y * w + x
					g_RegionsByPlot[idx] = g_RegionsByPlot[idx] or {}
					table.insert(g_RegionsByPlot[idx], row.Type)
				end
			end
		end
	end
	for row in excTable() do
		g_ExcludedIn[row.Type] = g_ExcludedIn[row.Type] or {}
		g_ExcludedIn[row.Type][row.Resource] = true
	end
end

-- Is this resource excluded from this plot's canonical region(s)?
local function ResourceIsExclude(resourceType, plotX, plotY)
	if not Options().ResourceGeo or not g_RegionsByPlot then return false end
	local w = Map.GetGridSize()
	local regions = g_RegionsByPlot[plotY * w + plotX]
	if regions then
		for _, region in ipairs(regions) do
			if g_ExcludedIn[region] and g_ExcludedIn[region][resourceType] then
				return true
			end
		end
	end
	return false
end

local g_WaterResource = {}
local function ResourceCanBeOnCoast(resource)
	if g_WaterResource[resource.Type] == nil then
		local ok = false
		for row in GameInfo.Resource_TerrainBooleans{ ResourceType = resource.Type } do
			if row.TerrainType == "TERRAIN_COAST" then ok = true end
		end
		g_WaterResource[resource.Type] = ok
	end
	return g_WaterResource[resource.Type]
end

-- Water rules shared by deposit and random placement (from the original METSL code)
local function WaterPlotRejects(resource, plot)
	if plot:GetTerrainType() == TerrainTypes.TERRAIN_OCEAN then return true end
	if plot:GetFeatureType() == FeatureTypes.FEATURE_ICE then return true end
	if FeatureTypes.FEATURE_ATOLL and plot:GetFeatureType() == FeatureTypes.FEATURE_ATOLL then return true end
	if plot:GetResourceType(-1) ~= -1 then return true end
	if not ResourceCanBeOnCoast(resource) then return true end
	if (plot:IsLake() or plot:IsAdjacentToLand()) and (resource.Type == "RESOURCE_WHALE" or resource.Type == "RESOURCE_OIL") then
		return true
	end
	return false
end

-- Original CanPlaceDepositAt (used for civ-requested resources), with correct coordinates
local function CanPlaceDepositAt(resource, plot)
	if plot:IsStartingPlot() then return false end
	if plot:GetPlotType() == PlotTypes.PLOT_OCEAN then
		if WaterPlotRejects(resource, plot) then return false end
	elseif not plot:CanHaveResource(resource.ID, true) then
		return false
	end
	local x, y = plot:GetX(), plot:GetY()
	for direction = 0, DirectionTypes.NUM_DIRECTION_TYPES - 1 do
		local other = Map.PlotDirection(x, y, direction)
		if other and other:GetResourceType() ~= -1 and other:GetResourceType() ~= resource.ID then
			return false
		end
	end
	return true
end

-- Canonical resources around each civilization's start
local function AddResourcesForCivs(def)
	local tableName = METSL_RequestedTable(def)
	if not GameInfo[tableName] then return end
	print("METSL: adding requested resources for civilizations")
	for i = 0, GameDefines.MAX_MAJOR_CIVS - 1 do
		local player = Players[i]
		if player and player:IsEverAlive() and player:GetStartingPlot() then
			local civ = GameInfo.Civilizations[player:GetCivilizationType()]
			local start = player:GetStartingPlot()
			local sx, sy = start:GetX(), start:GetY()
			local startArea = start:GetArea()
			for row in GameInfo[tableName]() do
				if civ and row.Type == civ.Type then
					for n = 1, 6 do
						local resType = row["Req" .. n]
						local resource = resType and GameInfo.Resources[resType]
						if resource then
							local yield = row["Yield" .. n] or 1
							local function Search(radius)
								local list, already = {}, false
								for dy = -radius, radius do
									for dx = -radius, radius do
										local p = Map.PlotXYWithRangeCheck(sx, sy, dx, dy, radius)
										if p and p ~= start then
											if p:GetResourceType(-1) == resource.ID then
												if not p:IsWater() and p:GetArea() == startArea then already = true end
											elseif CanPlaceDepositAt(resource, p) and (p:IsWater() or p:GetArea() == startArea) then
												table.insert(list, p)
											end
										end
									end
								end
								return list, already
							end
							local list, already = Search(3)
							if #list == 0 and not already then
								list = Search(6) -- larger search, place anyway
								already = false
							end
							if already then
								print("  " .. resType .. " already near " .. civ.Type)
							elseif #list > 0 then
								list[Rand(#list, "METSL requested resource")]:SetResourceType(resource.ID, yield)
								print("  placed " .. resType .. " (" .. yield .. ") for " .. civ.Type)
							else
								print("  no plot for " .. resType .. " near " .. civ.Type)
							end
						elseif resType then
							print("  requested resource " .. tostring(resType) .. " does not exist")
						end
					end
				end
			end
		end
	end
end

-- ===== Random resources: port of METSL's WorldBuilderRandomItems.lua =====
local function CountRealCivs(opt, def)
	local n = 0
	for i = 0, GameDefines.MAX_CIV_PLAYERS - 1 do
		local player = Players[i]
		if player and player:IsEverAlive() then
			if player:IsMinorCiv() then
				local minor = GameInfo.MinorCivilizations[player:GetMinorCivType()]
				-- city-states that will be removed (Only TSL) don't count
				if opt.MinorPlacement ~= METSL_MINOR_TSL_ONLY or (minor and METSL_MinorHasTSL(def, minor.Type)) then
					n = n + 1
				end
			else
				n = n + 1
			end
		end
	end
	return n
end

local g_RealNumCivAlive = 1

local function CalculateNumResourcesToAdd(resource)
	local rand1 = Map.Rand(resource.RandApp1, "MapGenerator CalculateNumResourcesToAdd-1")
	local rand2 = Map.Rand(resource.RandApp2, "MapGenerator CalculateNumResourcesToAdd-2")
	local rand3 = Map.Rand(resource.RandApp3, "MapGenerator CalculateNumResourcesToAdd-3")
	local rand4 = Map.Rand(resource.RandApp4, "MapGenerator CalculateNumResourcesToAdd-4")
	local baseCount = resource.ConstAppearance + rand1 + rand2 + rand3 + rand4
	local coeff = METSL_ResourceQuantityCoeff[Options().ResourceQuantity]
	if coeff then baseCount = baseCount * coeff end

	local numPossible, alreadyPlaced = 0, 0
	for _, plot in Plots() do
		if plot:CanHaveResource(resource.ID, false) then
			numPossible = numPossible + 1
		elseif plot:GetResourceType(-1) == resource.ID then
			numPossible = numPossible + 1
			alreadyPlaced = alreadyPlaced + 1
		end
	end

	if resource.AbsoluteBaseAmount and resource.AbsoluteBaseAmount > 0 then
		local amount = resource.AbsoluteBaseAmount
		if resource.AbsoluteVarPercent and resource.AbsoluteVarPercent > 0 then
			local lo = math.floor(amount - amount * resource.AbsoluteVarPercent / 100)
			local hi = math.floor(amount + amount * resource.AbsoluteVarPercent / 100)
			amount = lo + Map.Rand(hi - lo + 1, "METSL absolute amount")
		end
		return amount - alreadyPlaced
	end

	local landTiles = 0
	if resource.TilesPer > 0 then
		landTiles = math.floor(numPossible / resource.TilesPer)
	end
	local resourceCount
	if resource.Player and resource.Player > 0 then
		local players = math.floor((g_RealNumCivAlive * resource.Player) / 100)
		resourceCount = math.floor((baseCount * players) / 100)
	else
		resourceCount = math.floor((baseCount * landTiles) / 100)
	end
	resourceCount = math.max(1, resourceCount)
	if resourceCount < alreadyPlaced then
		resourceCount = 0
	else
		resourceCount = resourceCount - alreadyPlaced
	end
	return resourceCount
end

local function CanPlaceResourceAt(resource, plot, ignoreLatitude)
	local resourceID = resource.ID
	local area = plot:Area()
	local plotX, plotY = plot:GetX(), plot:GetY()

	if plot:IsStartingPlot() then return false end

	if plot:GetPlotType() == PlotTypes.PLOT_OCEAN then
		if WaterPlotRejects(resource, plot) then return false end
	elseif not plot:CanHaveResource(resourceID, ignoreLatitude) then
		return false
	end

	if ResourceIsExclude(resource.Type, plotX, plotY) then return false end

	for direction = 0, DirectionTypes.NUM_DIRECTION_TYPES - 1 do
		local other = Map.PlotDirection(plotX, plotY, direction)
		if other and other:GetResourceType() ~= -1 and other:GetResourceType() ~= resourceID then
			return false
		end
	end

	if plot:IsWater() then
		if ((Map.GetNumResourcesOnLand(resourceID) * 100) / (Map.GetNumResources(resourceID) + 1)) < resource.MinLandPercent then
			return false
		end
	end

	-- no resources of the same class (different type) nearby
	local resourceClass = GameInfo.ResourceClasses[resource.ResourceClassType]
	local uniqueRange = resourceClass.UniqueRange
	for dx = -uniqueRange, uniqueRange - 1 do
		for dy = -uniqueRange, uniqueRange - 1 do
			local other = Map.GetPlotXY(plotX, plotY, dx, dy)
			if other and other:Area():GetID() == area:GetID()
				and Map.PlotDistance(plotX, plotY, other:GetX(), other:GetY()) <= uniqueRange then
				local otherResource = GameInfo.Resources[other:GetResourceType()]
				if otherResource and otherResource.ResourceClassType == resource.ResourceClassType then
					return false
				end
			end
		end
	end

	-- none of the same resource nearby
	uniqueRange = resource.Unique + 1
	for dx = -uniqueRange, uniqueRange - 1 do
		for dy = -uniqueRange, uniqueRange - 1 do
			local other = Map.GetPlotXY(plotX, plotY, dx, dy)
			if other and other:Area():GetID() == area:GetID()
				and Map.PlotDistance(plotX, plotY, other:GetX(), other:GetY()) <= uniqueRange
				and other:GetResourceType() == resourceID then
				return false
			end
		end
	end
	return true
end

local function AddUniqueResourceType(resource)
	local resourceID = resource.ID
	local resourceCount = CalculateNumResourcesToAdd(resource)
	local ignoreLatitude = false
	local triedAreas = {}
	while true do
		local bestValue, bestArea = 0, nil
		for id, area in Map.Areas() do
			if triedAreas[area:GetID()] == nil then
				local value = area:GetNumTiles() / (area:CountNumUniqueResourceTypes() + 1)
				if value > bestValue then
					bestValue = value
					bestArea = area
				end
			end
		end
		if bestArea == nil then return end
		triedAreas[bestArea:GetID()] = true

		for _, plot in Plots(Shuffle) do
			if Map.GetNumResources(resourceID) >= resourceCount then break end
			if bestArea:GetID() == plot:Area():GetID() and CanPlaceResourceAt(resource, plot, ignoreLatitude) then
				plot:SetResourceType(resourceID, Map.GetRandomResourceQuantity(resourceID))
				local groupRange = resource.GroupRange
				for dx = -groupRange, groupRange - 1 do
					for dy = -groupRange, groupRange - 1 do
						if Map.GetNumResources(resourceID) < resourceCount then
							local other = Map.PlotXYWithRangeCheck(plot:GetX(), plot:GetY(), dx, dy, groupRange)
							if other and other:Area():GetID() == bestArea:GetID()
								and CanPlaceResourceAt(resource, other, ignoreLatitude)
								and Map.Rand(100, "addUniqueResourceType") < resource.GroupRand then
								other:SetResourceType(resourceID, Map.GetRandomResourceQuantity(resourceID))
							end
						end
					end
				end
			end
		end
	end
end

local function AddNonUniqueResourceType(resource)
	local resourceID = resource.ID
	local resourceCount = CalculateNumResourcesToAdd(resource)
	local ignoreLatitude = false
	if resourceCount <= 0 then return end
	for _, plot in Plots(Shuffle) do
		if CanPlaceResourceAt(resource, plot, ignoreLatitude) then
			plot:SetResourceType(resourceID, Map.GetRandomResourceQuantity(resourceID))
			resourceCount = resourceCount - 1
			local groupRange = resource.GroupRange
			for dx = -groupRange, groupRange - 1 do
				for dy = -groupRange, groupRange - 1 do
					if resourceCount > 0 then
						local other = Map.PlotXYWithRangeCheck(plot:GetX(), plot:GetY(), dx, dy, groupRange)
						if other and CanPlaceResourceAt(resource, other, ignoreLatitude)
							and Map.Rand(100, "addNonUniqueResourceType") < resource.GroupRand then
							other:SetResourceType(resourceID, Map.GetRandomResourceQuantity(resourceID))
							resourceCount = resourceCount - 1
						end
					end
				end
			end
			if resourceCount <= 0 then return end
		end
	end
end

local function AddRandomResources()
	print("METSL: adding random resources")
	local resources = {}
	for resource in GameInfo.Resources() do
		table.insert(resources, resource)
	end
	table.sort(resources, function(a, b)
		if a.PlacementOrder == b.PlacementOrder then return a.ID < b.ID end
		return a.PlacementOrder < b.PlacementOrder
	end)
	for _, resource in ipairs(resources) do
		if resource.Area then
			AddUniqueResourceType(resource)
		else
			AddNonUniqueResourceType(resource)
		end
	end
	for _, resource in ipairs(resources) do
		print("  " .. resource.Type .. ": " .. Map.GetNumResources(resource.ID))
	end
end

------------------------------------------------------------------------------
-- StartPlotSystem replacement: TSL + METSL resources
------------------------------------------------------------------------------
function StartPlotSystem()
	local def = Def()
	local opt = Options()
	print("-------------------------------")
	print("METSL: map " .. def.Key .. "  CS placement=" .. opt.MinorPlacement .. " resources=" .. opt.ResourceQuantity
		.. " NW=" .. tostring(opt.NaturalWonders) .. " geo=" .. tostring(opt.ResourceGeo)
		.. " requested=" .. tostring(opt.ResourceRequested))

	if opt.NaturalWonders then
		PlaceNaturalWonders(def)
	end

	PlaceMajorCivs(def)
	PlaceMinorCivs(def, opt)

	if opt.ResourceRequested then
		AddResourcesForCivs(def)
	end

	g_RealNumCivAlive = math.max(1, CountRealCivs(opt, def) - 1)
	if opt.ResourceGeo then
		BuildRegionData(def)
	end
	AddRandomResources()

	Map.RecalculateAreas()
	print("METSL: map generation finished")
	print("-------------------------------")
end
